insert into public.knowledge_items
(id,crop,problem_name,scientific_name,category,description,symptoms,verification_signs,recommended_action,prevention,warning_signs,extension_escalation,source,source_url,mvp_status,content_version,published)
values
('faw-001', 'Maize', 'Fall Armyworm', 'Spodoptera frugiperda', 'Pest (insect)', 'An invasive caterpillar pest that feeds inside the whorl (the tightly rolled young leaves at the plant''s center) and can cause severe damage if not caught early. Present across most of Zambia''s maize-growing areas since 2016.', '["Ragged, elongated holes in leaves, often in a row where the leaf was folded", "Window-pane patches where only the leaf surface was scraped away", "Sawdust-like droppings (frass) visible inside or near the whorl", "Damage concentrated in the whorl and, later, developing cobs"]', '["Look inside the whorl of affected plants for caterpillars: pale body with dark raised spots, and an upside-down ''Y'' marking on the head", "Four spots arranged in a square on the second-to-last body segment (distinguishes it from other similar caterpillars)", "Frass (small dark droppings) inside the whorl"]', 'Scout fields weekly starting soon after seedlings emerge (from about 2-3 weeks after planting). If caterpillars are found in the whorl before the plant is shoulder-high, treatment is more effective. Follow an integrated approach: handpicking/crushing where infestations are small, encouraging natural predators, and using an insecticide approved by local agricultural authorities if infestation is heavy — apply according to the product label and local extension guidance rather than a fixed generic dosage.', '["Scout regularly, especially in the first 6 weeks after planting", "Avoid staggered planting dates near already-infested fields where practical", "Intercropping and conserving natural predators (birds, parasitic wasps, egg/larval parasitoids) can reduce pressure", "Encouraging flowering plants at field margins can attract natural enemies of the pest"]', '["Widespread whorl damage across the field rather than a few plants", "Damage progressing to the developing cob"]', 'If infestation is heavy, spreading fast, or the farmer is unsure which insecticide is safe and approved for use', 'CABI Plantwise / Invasive Species Compendium; Agroberichten Buitenland identification guide; IPPC pest report (Zambia Agriculture Research Institute)', 'https://www.cabi.org/isc/datasheet/29810', 'core', '1.1', true),
('msv-001', 'Maize', 'Maize Streak Disease', 'Maize streak virus (MSV)', 'Disease (viral)', 'A viral disease spread by leafhopper insects. It is one of the most damaging maize diseases in Africa and can cause total yield loss if plants are infected while very young.', '["Narrow, broken yellow to pale-green streaks running along the leaf veins", "Streaks visible on both leaf surfaces", "Severe stunting if infection happens at the 4-5 leaf stage", "Unusual bunching of leaves/shoots and reddish leaf discoloration in severe cases"]', '["Yellow/pale streaks parallel to leaf veins, not random blotches", "Check for leafhoppers (small, pale, wedge-shaped insects) on the underside of leaves", "Younger plants showing more severe stunting than older ones nearby"]', 'Remove and destroy infected plants as soon as they''re spotted (pull the whole plant, place in a sack rather than dropping it in the field, so leafhoppers don''t move to healthy plants). Keep fields and surrounds free of grasses and volunteer cereal plants, which host the leafhopper.', '["Use certified, disease-free seed", "Plant early in the rainy season so seedlings pass the vulnerable early stage quickly", "Remove grass weeds and old cereal crop residue near the field", "Avoid staggered/late planting near already-infected fields where possible"]', '["Infection spreading rapidly across a young field", "Severe stunting affecting a large portion of seedlings"]', 'If a large share of young seedlings across the field show streaking and stunting, since replanting decisions may be needed', 'CABI Plantwise Pest Management Decision Guide, Maize Streak Virus (Ethiopia/Malawi editions)', 'https://farmknowledge.info/Resource/627880', 'core', '1.1', true),
('rust-001', 'Maize', 'Common Rust', 'Puccinia sorghi', 'Disease (fungal)', 'A fungal leaf disease that produces raised, rust-colored pustules on leaves. It''s favored by cool, humid conditions and near-100% relative humidity with dew, and usually causes limited yield loss unless infection is severe and early.', '["Circular to elongated golden-brown or cinnamon-brown, powdery pustules on both leaf surfaces", "Pustules turn darker brown to black as the plant matures and the fungus produces its resting spore stage", "In severe early infections, affected leaves may yellow and die early, and infection can spread to leaf sheaths"]', '["Rub a pustule gently — rust diseases leave a rusty, powdery residue on your finger", "Pustules scattered rather than in neat rows or rectangular blocks (helps distinguish from Gray Leaf Spot)", "Present on both sides of the leaf, not just one"]', 'For most smallholder situations common rust causes limited damage and may not need chemical treatment. If pustules are dense and appear early in the season on many plants (roughly six or more pustules per leaf on average), a fungicide recommended by a local extension officer or approved agro-dealer can help, especially on susceptible varieties.', '["Plant rust-resistant maize varieties where available", "Avoid excessive nitrogen application, which can increase susceptibility", "Rotate crops and manage field residue where practical"]', '["Pustules coalescing (merging) across large parts of the leaf", "Widespread early-season infection across the field"]', 'If pustules are dense on most plants early in the season and the farmer is unsure whether fungicide treatment is worthwhile', 'University of Tennessee Crops guide; Plantwise Plus Knowledge Bank; Agri Farming pest and disease management reference', 'https://guide.utcrops.com/corn/foliar-disease/common-rust', 'core', '1.1', true),
('gls-001', 'Maize', 'Gray Leaf Spot', 'Cercospora zeae-maydis', 'Disease (fungal)', 'A fungal disease causing rectangular leaf lesions that can merge and destroy large areas of leaf tissue, significantly reducing yield if it strikes before grain fill. Confirmed as a serious problem in several African maize-growing regions.', '["Small tan to yellow spots on lower leaves first, appearing before or around flowering", "Spots elongate into narrow, rectangular, gray-brown lesions running parallel to leaf veins", "Lesions can merge, causing large areas of dead, blighted leaf tissue", "Symptoms progress from lower leaves upward over time"]', '["Lesions are straight-edged and rectangular (boxy), unlike the round scattered pustules of Common Rust", "Lesions run parallel to the leaf veins and generally do not cross major veins", "Symptoms start on the lowest, oldest leaves"]', 'Where lesions are still limited to lower leaves, monitor closely. If lesions are spreading upward and merging before the plant reaches grain-filling stage, a fungicide recommended by extension services may be justified given the risk of yield loss.', '["Rotate maize with a non-cereal crop where land allows", "Bury or remove old maize residue rather than leaving it on the surface", "Plant resistant hybrids where available", "Avoid dense planting that reduces airflow between plants"]', '["Lesions merging into large blighted patches", "Disease reaching the upper leaves before or during grain fill"]', 'If lesions are spreading rapidly up the plant before grain fill, since this stage carries the highest risk of serious yield loss', 'UK DFID Crop Protection Programme report (Kenya); Cornell CALS Field Crops; Plantix agronomy guide', 'https://assets.publishing.service.gov.uk/media/57a08d10e5274a31e0001604/R7566_FTR_Appendix_6.pdf', 'core', '1.1', true),
('stemborer-001', 'Maize', 'Stem Borer Damage', 'Busseola fusca / Chilo partellus', 'Pest (insect)', 'Caterpillars that start by feeding on young whorl leaves, then bore into the stem itself, where they''re protected from most sprays. One of the most significant insect pests of maize across sub-Saharan Africa, including Zambia, where both species have been recorded across different agroecological regions.', '["Rows of small holes (''shot holes'') or window-like patches on unfolding whorl leaves", "Central shoot/growing point dries and dies (''dead heart'') on young plants", "Visible bore holes on the stem, often near the nodes", "Sawdust-like frass near stem entry holes", "Weak, easily broken (lodging) stems in older, heavily tunneled plants"]', '["Rows of holes across a leaf that align when the leaf is unfolded — a sign the damage happened while the leaf was still rolled in the whorl", "Dead, dried central shoot that pulls out easily (''dead heart''), with the surrounding leaves still green", "Cutting open an affected stem reveals a tunnel and a caterpillar with a grayish or yellow-brown body"]', 'Check plants for early shot-hole damage from about 4-6 weeks after planting. Remove and destroy plants showing dead heart, since the larva is usually still inside and will move to the next plant otherwise. Destroy old maize stubble after harvest rather than leaving it in the field, since larvae overwinter there. Where infestation is heavy, an insecticide approved for stem borer control and recommended by local extension services can be applied while larvae are still in the whorl, before they bore into the stem — controlling the first generation is important, since a second generation is typically more numerous and harder to manage.', '["Destroy and remove maize stubble immediately after harvest", "Intercropping (e.g., with legumes) can reduce infestation pressure", "Plant early in the rainy season where possible", "Use tolerant/resistant varieties where available"]', '["Dead heart appearing on many plants across the field, not isolated cases", "Stems breaking/lodging due to internal tunneling"]', 'If dead heart or stem tunneling is widespread across the field, or if the farmer is unsure which insecticide is safe to use at this crop stage', 'CIMMYT insect pest reference; TNAU Agritech Portal; Plantwise Pest Management Decision Guide; peer-reviewed Zambia stalk borer field survey (Springer)', 'https://agritech.tnau.ac.in/crop_protection/maize/crop_prot_maize_2.html', 'core', '1.1', true),
('nitrogen-001', 'Maize', 'Nitrogen Deficiency', '', 'Abiotic (nutrient deficiency)', 'A shortage of available nitrogen in the soil, one of the most common nutrient problems in smallholder maize, especially on sandy or heavily leached soils, or where fertilizer was applied too little or too late.', '["Yellowing that starts at the tip of older, lower leaves and spreads inward in a V-shape toward the leaf''s midrib", "Older/lower leaves affected first — nitrogen moves from old leaves to new growth inside the plant", "Overall pale green, stunted, thin-stalked plants", "Reduced cob size and incomplete kernel fill in severe cases"]', '["Check the OLDER, lower leaves first — nitrogen deficiency shows there before younger leaves", "Look for the characteristic V-shaped yellowing starting at the leaf tip and running down the midrib", "Compare against nearby better-fertilized plants if available"]', 'Apply nitrogen fertilizer (e.g., urea or a recommended basal/top-dressing compound such as 7:14:7) at the rate and timing recommended for the local soil type and yield target — a local extension officer or soil test can help determine the right amount for the field, since over-application wastes money and can harm the crop. Top-dressing is generally most effective when applied 3.5 to 6 weeks after crop emergence, and may be split into two applications on sandy soils.', '["Follow recommended fertilizer application timing (basal at/before planting, top-dressing 3.5-6 weeks after emergence)", "Add organic matter/manure to improve soil nitrogen-holding capacity", "Get soil tested periodically where possible"]', '["Yellowing affecting most of the field rather than a few plants", "Severe stunting alongside the yellowing"]', 'If the farmer is unsure how much fertilizer to apply, or if yellowing is severe and widespread despite fertilizer already being applied', 'Yara crop nutrition guide; ICL Growing Solutions maize nutrient deficiency guide; regional Maize Growers Guide (fertiliser and top-dressing timing)', 'https://www.yara.nl/en-my/gewasvoeding/maize/nutrient-deficiencies-maize/nitrogen-deficiency-maize/', 'core', '1.1', true),
('drought-001', 'Maize', 'Drought Stress', '', 'Abiotic (environmental stress)', 'Water shortage severe enough to affect plant growth, common in Zambia and Zimbabwe during dry spells or poorly-timed rainy seasons. Maize is especially sensitive to drought around flowering/silking, and to heat above about 38°C, which affects pollen viability.', '["Leaves rolling or folding lengthwise (like a drinking straw), especially in the heat of the day", "Leaves that stay rolled even in early morning/evening as stress worsens", "Grayish-green or dull leaf color", "Stunted growth and delayed silking/tasseling", "Poor kernel formation if drought hits around flowering"]', '["Check if leaves unroll in the cool of early morning — if they do, it''s likely drought stress rather than another cause", "Confirm soil is genuinely dry by feel/appearance a few centimeters below the surface", "Rule out waterlogging and disease as competing explanations for wilting"]', 'Irrigate if any water source is available, prioritizing the four-week period spanning flowering (tasseling and silking), since that''s when drought causes the most yield damage. Mulching, pot-holing, or tied-ridging can help retain soil moisture, especially in drier areas. If no irrigation is possible, focus on minimizing further stress (e.g., avoid unnecessary soil disturbance) and prepare for possible yield loss.', '["Choose drought-tolerant maize varieties where available", "Mulch, pot-hole, or use tied-ridges to conserve soil moisture, particularly in low-rainfall areas", "Plant as early as possible within the recommended planting window for the local rainy season, since delayed planting increases drought risk at flowering", "Improve soil organic matter to boost water retention"]', '["Leaves remaining rolled through the cool morning hours", "Drought occurring during flowering/silking, the most sensitive stage"]', 'If drought is prolonged and severe with no irrigation option and the farmer needs guidance on salvaging the crop or planning for the season', 'Peer-reviewed drought physiology research (Acta Botanica Croatica; Frontiers in Plant Science mitigation review); regional Maize Growers Guide', 'https://doi.org/10.3389/fpls.2022.875774', 'core', '1.1', true),
('waterlog-001', 'Maize', 'Water Stress / Waterlogging', '', 'Abiotic (environmental stress)', 'Excess standing or saturated soil water that deprives maize roots of oxygen, common after heavy rain in poorly-drained fields. Maize is notably sensitive to waterlogging compared to many other cereals.', '["Yellowing starting on older/lower leaves, spreading from the leaf tip", "Leaves overall looking pale, chlorotic (washed-out yellow-green)", "Stunted plant height and reduced root growth", "Visible standing water or saturated, muddy soil around the plant base", "Roots appearing dark, mushy, or decayed if the plant is uprooted"]', '["Confirm recent heavy rain and standing/saturated soil rather than dry conditions", "Uproot a plant and check for dark, soft, decaying roots (distinguishes from drought, where roots stay firm)", "Yellowing pattern similar to nitrogen deficiency — check soil wetness to tell them apart"]', 'Improve drainage where possible (open small channels to let standing water escape). Avoid applying fertilizer while soil is waterlogged, since roots can''t take it up and it can wash away. Once the field drains, monitor for delayed recovery.', '["Avoid planting maize in low-lying, poorly-drained fields where avoidable, unless practices like ridge tillage, drainage, and early planting are used", "Maintain drainage channels/ridging, especially before the peak rainy season", "Avoid soil compaction from heavy machinery or livestock on wet soil"]', '["Standing water persisting for several days", "Roots showing clear decay when checked"]', 'If waterlogging is recurring on the same field each season, since a longer-term drainage solution may be needed', 'Peer-reviewed waterlogging physiology studies (Agricultural Science Digest; Journal of Agricultural Science and Technology); regional Maize Growers Guide', 'https://arccjournals.com/journal/agricultural-science-digest/DF-500', 'core', '1.1', true)
