-- Seed the eight core maize knowledge items required by diagnosis foreign keys.
-- Review the bundled knowledge base and sources before production use.
on conflict (id) do update set
  problem_name = excluded.problem_name, description = excluded.description, symptoms = excluded.symptoms,
  verification_signs = excluded.verification_signs, recommended_action = excluded.recommended_action,
  prevention = excluded.prevention, warning_signs = excluded.warning_signs, extension_escalation = excluded.extension_escalation,
  source = excluded.source, source_url = excluded.source_url, content_version = excluded.content_version, published = true, updated_at = now();
